const payload = $input.first().json.body || $input.first().json;
const event = $input.first().json.headers?.['x-github-event'] || 'unknown';

// Only process pull_request events with relevant actions
const validActions = ['opened', 'synchronize', 'reopened'];
const action = payload.action || '';
const isPR = event === 'pull_request' && validActions.includes(action);

if (!isPR) {
  return [{ json: { skip: true, reason: `Not a PR event: ${event}/${action}` } }];
}

const pr = payload.pull_request || {};
const repo = payload.repository || {};

return [{
  json: {
    skip: false,
    event: event,
    action: action,
    pr_number: pr.number,
    pr_title: pr.title,
    pr_branch: pr.head?.ref || 'unknown',
    base_branch: pr.base?.ref || 'main',
    repo_url: repo.clone_url || repo.html_url,
    repo_full_name: repo.full_name,
    pr_url: pr.html_url,
    statuses_url: pr.statuses_url,
    sha: pr.head?.sha
  }
}];

const prev = $('Parse GitHub Event').first().json;
const validation = $input.first().json;

const passed = validation.passed === true;
const state = passed ? 'success' : 'failure';
const description = passed 
  ? 'All checks passed' 
  : `Found ${validation.summary?.lint_issues || 0} lint, ${validation.summary?.vulnerabilities || 0} vuln, ${validation.summary?.secrets_found || 0} secrets`;

return [{
  json: {
    sha: prev.sha,
    statuses_url: prev.statuses_url,
    repo_full_name: prev.repo_full_name,
    pr_number: prev.pr_number,
    state: state,
    description: description,
    validation: validation
  }
}];

const prev = $('Prepare Status').first().json;

return [{
  json: {
    success: true,
    pr_number: prev.pr_number,
    state: prev.state,
    description: prev.description,
    validation_summary: prev.validation?.summary,
    timestamp: new Date().toISOString()
  }
}];
